// Match std::stoi by consuming a signed decimal prefix and ignoring suffix characters.
fn parse_i32_like_stoi(input: &str) -> i32 {
    let trimmed = input.trim_start_matches(|ch: char| ch.is_ascii_whitespace());
    let bytes = trimmed.as_bytes();
    let mut index = 0usize;
    let mut negative = false;

    if index < bytes.len() {
        match bytes[index] {
            b'+' => index += 1,
            b'-' => {
                negative = true;
                index += 1;
            }
            _ => {}
        }
    }

    let digit_start = index;
    let mut magnitude = 0i64;

    while index < bytes.len() && bytes[index].is_ascii_digit() {
        magnitude = magnitude
            .checked_mul(10)
            .and_then(|value| value.checked_add(i64::from(bytes[index] - b'0')))
            .unwrap_or_else(|| panic!("stoi"));
        index += 1;
    }

    if index == digit_start {
        panic!("stoi");
    }

    let signed = if negative { -magnitude } else { magnitude };

    if signed < i32::MIN as i64 || signed > i32::MAX as i64 {
        panic!("stoi");
    }

    signed as i32
}

