use std::collections::HashMap;
use std::hash::Hash;

#[derive(Clone, Debug, Default)]
pub struct HopscotchMap<K, V> {
    inner: HashMap<K, V>,
}

impl<K, V> HopscotchMap<K, V>
where
    K: Eq + Hash,
{
    pub fn new() -> Self {
        Self {
            inner: HashMap::new(),
        }
    }

    pub fn insert(&mut self, entry: (K, V)) -> Option<V> {
        self.inner.insert(entry.0, entry.1)
    }
}

impl<K, V> HopscotchMap<K, V>
where
    K: Eq + Hash,
    V: Default,
{
    pub fn set_indexed(&mut self, key: K, value: V) {
        let slot = self.inner.entry(key).or_default();
        *slot = value;
    }
}

impl<K, V> PartialEq for HopscotchMap<K, V>
where
    K: Eq + Hash,
    V: PartialEq,
{
    fn eq(&self, other: &Self) -> bool {
        self.inner == other.inner
    }
}

impl<K, V> Eq for HopscotchMap<K, V>
where
    K: Eq + Hash,
    V: Eq,
{
}

